#!/usr/bin/env bash
# СУДИТ: hooks/lib/archive_relay.py hooks/session-collector.sh
# probe_D1352.sh — срок напоминания владельцу об отказе архиватора считается работой, а не часами.
#
# Повод (21 ноября 2026, решение владельца на вопрос о сроке: «по работе, пунктом в очередь»). Напоминание «архиватор
# не уносит закрытые пункты» наступало, когда отказ висел дольше суток ПО ЧАСАМ. Правило владельца в корне R4 карты:
# время не показатель при периодичности.
# Срок берётся там же, где его берёт сборщик (`ARCHIVE_RELAY_RUNS` в hooks/session-collector.sh): первая редакция пробы
# подавала прибору 86400 и после смены единицы зеленела сама собой — 86400 запусков не наберётся никогда.
# Три рамки. «Часы без работы»: отказ встречен двое суток назад, прибор позван один раз — напоминания быть не должно.
# «Работа без часов»: прибор позван столько раз, сколько велит срок, в одну и ту же секунду — напоминание обязано выйти
# (рамка умеет отвечать «да»). Контроль: только что встреченный отказ после одного вызова молчит.
# Проверка результата: bash hooks/tests/fixtures/probe_D1352.sh → 0 — срок считается запусками; 1 — часами (срок в
#   сборщике задан в секундах, либо двое суток без работы дали напоминание, либо запуски без часов его не дали);
#   2 — не измерено (нет прибора или сборщика, контроль не сошёлся).
set -uo pipefail
REPO="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
PY="$REPO/hooks/lib/archive_relay.py"; SC="$REPO/hooks/session-collector.sh"
[ -f "$PY" ] && [ -f "$SC" ] && command -v python3 >/dev/null 2>&1 || { echo "нет прибора напоминания либо сборщика — не измерено"; exit 2; }
NEED=$(grep -oE 'ARCHIVE_RELAY_RUNS:-[0-9]+' "$SC" | head -1 | grep -oE '[0-9]+$')
[ -n "${NEED:-}" ] || { echo "сборщик не задаёт срок в запусках (ARCHIVE_RELAY_RUNS) — срок считается часами"; exit 1; }
W=$(mktemp -d) || exit 2
trap 'rm -rf "$W"' EXIT
NOW=$(date +%s)
call() {   # <сейчас> → вывод прибора; состояние — "$W/st"
    printf '  · D1: судит по форме\n' | python3 "$PY" "$W/st" "$1" "$NEED" "" "" 2>/dev/null
}
rm -f "$W/st"
[ -z "$(call "$NOW")" ] || { echo "контроль: только что встреченный отказ дал напоминание после одного вызова — не измерено"; exit 2; }
# Часы без работы: первая встреча двое суток назад, один вызов.
printf 'D1\t%s\t0\t0\tпричина\n' "$((NOW - 172800))" > "$W/st"
if [ -n "$(call "$NOW")" ]; then
    echo "двое суток по часам при одном запуске — напоминание вышло: срок считается часами"
    exit 1
fi
# Работа без часов: срок запусков в одну и ту же секунду.
rm -f "$W/st"; out=""; i=0
while [ "$i" -lt "$NEED" ]; do out=$(call "$NOW"); i=$((i + 1)); done
if [ -z "$out" ]; then
    echo "запусков ${NEED} за одну секунду — напоминания нет: срок считается не запусками"
    exit 1
fi
echo "срок напоминания считается работой: ${NEED} запусков подряд, часы его не двигают"
exit 0
